            return string.format('Stopped: %s. Retrying in %ds (failure %d of %d).',tracker.failure_reason,math.ceil(left),
                tracker.fail_streak or 1,M.MAX_FAIL_STREAK)
        end
        if stuck and tracker.need_trigger==true then
            local wait=(tracker.failed_at or 0)+M.LATCH_RETRY-get_time_since_inject()
            if wait>0 then
                return string.format('Stopped: %s. Automatic retry in %ds, or use Run town service.',tracker.failure_reason,math.ceil(wait))
            end
        end
        return 'Stopped: '..tracker.failure_reason..'. Use Run town service to retry.'
    end
    if M.busy() then
        local player,world=get_local_player(),get_current_world()
        if not player or player:is_dead()~=false then return 'Waiting for a living player.' end
        if not world or world:get_current_zone_name()=='[sno none]' then return 'Waiting for the world to load.' end
        if is_chat_open() then return 'Paused while chat is open.' end
        return 'Servicing '..tostring(tracker.external_caller or 'bags')..(tracker.teleport and ' - travelling to town' or '')
    end
    if not settings.get_keybind_state() then return 'Automatic service paused by keybind. Run town service still works.' end
    if tracker.outcome=='completed' then return 'Completed. Watching bags and repairs.' end
    return 'Ready. Watching bags and repairs.'
end
